import java.util.*;
class Util{static <T extends Comparable<T>> T max(List<T> a){T m=a.get(0);for(T x:a)if(x.compareTo(m)>0)m=x;return m;}}
public class Main{public static void main(String[]a){Scanner s=new Scanner(System.in);int n=s.nextInt();List<Integer> x=new ArrayList<>();for(int i=0;i<n;i++)x.add(s.nextInt());System.out.println(Util.max(x));}}

